/// <summary>
/// Per company and count type: whether the counting journal the supervisor creates in the control
/// center is posted straight away (Auto-post) or left for the back office.
/// </summary>
public class HSMobileOpsCountTypeSetup extends common
{
}

Method.Source:
public static HSMobileOpsCountTypeSetup find(HSMobileOpsCountMasterType _type)
{
    HSMobileOpsCountTypeSetup setup;

    select firstonly setup where setup.MasterType == _type;
    return setup;
}

/// <summary>
/// One row per count type, Auto-post off, so the form always shows all three.
/// </summary>
public static void ensureSeeded()
{
    HSMobileOpsCountTypeSetup setup;
    container                 types = [HSMobileOpsCountMasterType::WallToWall, HSMobileOpsCountMasterType::Hazard, HSMobileOpsCountMasterType::Blind];
    int                       i;

    ttsbegin;
    for (i = 1; i <= conLen(types); i++)
    {
        if (!HSMobileOpsCountTypeSetup::find(conPeek(types, i)).RecId)
        {
            setup.clear();
            setup.MasterType = conPeek(types, i);
            setup.AutoPost   = NoYes::No;
            setup.insert();
        }
    }
    ttscommit;
}
